#!/usr/bin/env python3
"""Refresh a static page from two public YouTube channels' video descriptions and GitHub repo metadata. Run manually after checking results; do not silently deploy invalid sources."""
import html,json,re,subprocess,urllib.request,datetime,pathlib,base64,gzip
ROOT=pathlib.Path(__file__).parent
CHANNELS={'JunSun':'https://www.youtube.com/@junsun1710/videos','Github Awesome':'https://www.youtube.com/@GithubAwesome/videos'}
def latest_ids(url,limit):
 raw=subprocess.check_output(['yt-dlp','--flat-playlist','--playlist-end',str(limit),'--dump-json','--no-warnings',url],stderr=subprocess.DEVNULL,timeout=50)
 return [j['id'] for j in map(json.loads,raw.splitlines()) if re.fullmatch(r'[A-Za-z0-9_-]{11}',j.get('id',''))]
VIDS={ch:latest_ids(url,n) for ch,url,n in [('JunSun',CHANNELS['JunSun'],3),('Github Awesome',CHANNELS['Github Awesome'],2)]}
if any(len(v)<2 for v in VIDS.values()):raise RuntimeError('YouTube latest list incomplete; leave published snapshot unchanged')
# Recover published history before refreshing. Never discard a failed archive read.
ARCHIVE_SEED=''
archive=json.loads(gzip.decompress(base64.b64decode(ARCHIVE_SEED)))
if (ROOT/'archive.json').exists():archive.update(json.loads((ROOT/'archive.json').read_text()))
with urllib.request.urlopen('https://raw.githubusercontent.com/Rkinstinct/github-video-trends/main/index.html',timeout=20) as response:published=response.read().decode()
packed=re.search(r'id="radar-archive" type="application/octet-stream">([^<]+)</script>',published)
if packed:archive.update(json.loads(gzip.decompress(base64.b64decode(packed.group(1)))))
now=datetime.datetime.now(datetime.timezone.utc).astimezone(__import__('zoneinfo').ZoneInfo('Asia/Jerusalem')).strftime('%d.%m.%Y %H:%M %Z')
def getvideo(vid):
 raw=subprocess.check_output(['yt-dlp','--skip-download','--dump-single-json','--no-warnings',f'https://www.youtube.com/watch?v={vid}'],stderr=subprocess.DEVNULL,timeout=30)
 j=json.loads(raw)
 return {'title':j['title'],'date':j.get('upload_date',''),'url':j['webpage_url'],'description':j.get('description') or ''}
videos=[(channel,getvideo(vid)) for channel,ids in VIDS.items() for vid in ids]
repos={}
for channel,v in videos:
 for slug in re.findall(r'https://github.com/([\w.-]+/[\w.-]+)',v['description']):
  slug=slug.rstrip('.,)')
  if slug not in repos:repos[slug]={'channel':channel,'video':v,'sources':[]}
  if not any(s['url']==v['url'] for s in repos[slug]['sources']):repos[slug]['sources'].append({'channel':channel,'url':v['url'],'title':v['title'],'date':v['date']})
# Newest source videos first, then description order. Verify direct GitHub links before inclusion.
featured=list(repos)
verified=[]
failures=[]
for slug in featured:
 if slug not in repos:continue
 try:
  req=urllib.request.Request('https://api.github.com/repos/'+slug,headers={'User-Agent':'Rkinstinct-GitHub-video-trends'})
  with urllib.request.urlopen(req,timeout=10) as response:j=json.load(response)
  if j.get('full_name','').lower()!=slug.lower() or j.get('archived'):continue
  verified.append({'name':j['full_name'],'description':j.get('description') or 'תיאור לא זמין במאגר','url':j['html_url'],'stars':j['stargazers_count'],'language':j.get('language') or '—','channel':repos[slug]['channel'],'video':repos[slug]['video']['url'],'sources':repos[slug]['sources'],'channels':list(dict.fromkeys(s['channel'] for s in repos[slug]['sources']))})
 except Exception as e:
  failures.append(slug)
  print('verification failed',slug,e)
if failures:raise RuntimeError('Repository verification incomplete; leave published snapshot unchanged: '+', '.join(failures))
if len(verified)<4:raise RuntimeError('Too few verified repos; do not deploy')
(ROOT/'snapshot.json').write_text(json.dumps({'updated':now,'videos':[{'channel':ch,'title':v['title'],'date':v['date'],'url':v['url']} for ch,v in videos],'repos':verified},ensure_ascii=False,indent=2))
def esc(x):return html.escape(str(x),quote=True)
def card(r):
 channels=' | '.join(r['channels'])
 links=''.join(f'<a href="{esc(s["url"])}" rel="noopener" target="_blank">{esc(s["channel"])} · {esc(s["date"])} ↗</a>' for s in r['sources'])
 return f'''<article class="card" data-channels="{esc('|'.join(r['channels']))}"><div class="eyebrow">{esc(channels)} / {esc(r['language'])}</div><h3 dir="ltr">{esc(r['name'])}</h3><p>{esc(r['description'])}</p><div class="meta"><span>★ {r['stars']:,} <small>כעת, לא קצב צמיחה</small></span><a href="{esc(r['url'])}" rel="noopener" target="_blank">מאגר ↗</a></div><div class="sources"><small>סרטוני מקור</small>{links}</div></article>'''
def video(ch,v):return f'<li><a href="{esc(v["url"])}" rel="noopener" target="_blank">{esc(v["title"])}</a> <small>{esc(ch)} · {esc(v["date"])}</small></li>'
page='''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#030304"><meta name="description" content="פרויקטי GitHub שעלו בשני ערוצי YouTube, עם קישור לסרטון ולמאגר מאומת. מתעדכן בסקירה יומית."><meta property="og:title" content="GitHub Radar | DATA&AI"><meta property="og:description" content="מה בלט בערוצי JunSun ו-Github Awesome, עם מקורות ישירים"><title>GitHub Radar | DATA&AI</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Heebo:wght@400;500;600;700;800&family=Inter:wght@400;600;700&family=Space+Grotesk:wght@500;700&family=JetBrains+Mono:wght@400;600&display=swap" rel="stylesheet"><style>
:root{--bg:#030304;--surface:#0f1115;--line:#303641;--orange:#F7931A;--gold:#FFD600;--muted:#b5c0cf;color-scheme:dark}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 5% 0%,#342007,transparent 38%),var(--bg);color:#f8f9fb;font:16px/1.7 'Heebo',sans-serif}.wrap{max-width:1140px;width:calc(100% - 36px);margin:auto}a{color:var(--orange);text-underline-offset:4px}a:hover{color:var(--gold)}a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.top{background:#030304de;border-bottom:1px solid var(--line);backdrop-filter:blur(12px);position:sticky;top:0;z-index:10}.top .wrap{display:flex;align-items:center;justify-content:space-between;gap:15px;min-height:65px}.brand{text-decoration:none;color:#fff;font:700 1.1rem 'Space Grotesk','Heebo'}.brand span{color:var(--orange)}nav{display:flex;gap:18px;white-space:nowrap;overflow:auto}nav a{text-decoration:none;color:var(--muted);font-size:.85rem;min-height:44px;display:flex;align-items:center}.hero{padding:85px 0 64px;border-bottom:1px solid var(--line)}.eyebrow{color:var(--orange);font:600 .76rem 'JetBrains Mono','Heebo';letter-spacing:.05em}.hero h1{font:700 clamp(2.8rem,8vw,5.7rem)/1.1 'Space Grotesk','Heebo';margin:15px 0}.hero h1 span{background:linear-gradient(95deg,var(--orange),var(--gold));color:transparent;background-clip:text}.lead{max-width:750px;color:#d3d9e2;font-size:1.15rem}.badge{display:inline-block;border:1px solid #604018;border-radius:999px;background:#39240d90;padding:6px 14px;color:var(--gold);font:.78rem 'JetBrains Mono','Heebo';margin:12px 0}.section{padding:52px 0;border-bottom:1px solid #252a32}.section h2{font-size:clamp(1.9rem,4vw,2.7rem);line-height:1.2;margin:7px 0 16px}.section> .wrap >p{max-width:800px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:22px}.card{border:1px solid #544023;border-radius:17px;background:linear-gradient(140deg,#211910,#0f1115 60%);box-shadow:inset 0 1px #ffffff17,0 18px 40px #0006;padding:22px;min-width:0;display:flex;flex-direction:column}.date-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.date-tabs button{background:#15171b;color:#dedfe0;border:1px solid #46505e;border-radius:12px;min-height:44px;padding:10px 15px;cursor:pointer}.date-tabs button[aria-pressed=true]{background:var(--orange);color:#171007}#date-note{color:var(--muted);font-size:.85rem}.card[hidden]{display:none!important}.sources{display:flex;flex-direction:column;gap:6px;border-top:1px solid #354052;margin-top:12px;padding-top:12px;font-size:.8rem}.sources small{color:var(--muted)}.coverage{color:var(--gold);margin:18px 0}.card h3{font:600 1.2rem 'Space Grotesk','Inter';word-break:break-word;text-align:left;margin:14px 0 7px}.card p{color:#cad3dd;line-height:1.65;flex:1}.meta{display:flex;align-items:center;gap:14px;flex-wrap:wrap;border-top:1px solid #354052;padding-top:13px;font:.82rem 'JetBrains Mono','Heebo'}.meta small{display:block;color:var(--muted);font:.68rem 'Heebo'}.filter{display:flex;gap:8px;flex-wrap:wrap}.filter button{background:#15171b;color:#dedfe0;border:1px solid #46505e;border-radius:999px;min-height:44px;padding:8px 18px;font:600 .9rem 'Heebo';cursor:pointer}.filter button[aria-pressed=true]{border-color:var(--orange);color:#171007;background:var(--orange)}li{margin:10px 0}li small{color:var(--muted);margin-inline-start:9px}footer{color:var(--muted);font-size:.82rem;padding:35px 0}footer .wrap{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}@media(max-width:850px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.top .wrap{display:block;padding:10px 0}nav{gap:16px}.hero{padding:50px 0}.cards{grid-template-columns:1fr}.section{padding:40px 0}.card{padding:19px}body{font-size:15px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
.reading-toggle{margin-top:14px;border:1px solid #F7931A;border-radius:10px;background:#241807;color:#FFD600;min-height:44px;padding:10px 14px;cursor:pointer;font:600 .9rem Heebo,sans-serif}.reading-toggle[aria-pressed=true]{background:#F7931A;color:#171007}.reading-hint{color:#b5c0cf;font-size:.85rem}.saved-copy-tools{margin:18px 0 24px}.saved-copy-tools button{background:#241807;color:#FFD600;border:1px solid #F7931A;border-radius:10px;min-height:44px;padding:10px 14px;margin:0 0 8px 8px;font:600 .9rem Heebo,sans-serif;cursor:pointer}.saved-copy-tools p,.saved-copy-tools label{color:#b5c0cf;line-height:1.7}.saved-copy-tools textarea{display:block;box-sizing:border-box;width:100%;max-width:100%;margin:10px 0;background:#101216;color:#f3f3f3;border:1px solid #544023;border-radius:10px;padding:12px;font:14px/1.6 monospace;resize:vertical;overflow-wrap:anywhere}.saved-copy-tools [hidden]{display:none}
</style></head><body><header class="top"><div class="wrap"><a class="brand" href="https://rkinstinct.github.io/data-ai-hub/">DATA<span>&</span>AI / GITHUB RADAR</a><nav><a href="#repos">פרויקטים</a><a href="#videos">סרטונים</a><a href="#method">איך נבחרים</a></nav></div></header><main><div class="hero"><div class="wrap"><div class="eyebrow">OPEN SOURCE / TWO VIDEO SOURCES</div><h1>GitHub <span>Radar</span></h1><p class="lead">פרויקטים שהוזכרו בערוצי <a href="https://www.youtube.com/@junsun1710/videos">JunSun</a> ו-<a href="https://www.youtube.com/@GithubAwesome/videos">Github Awesome</a>. כל פריט מקשר לסרטון שמזכיר אותו ולמאגר GitHub שנבדק. זה רדאר לסקירה, לא מדד רשמי של GitHub Trending.</p><span class="badge">תמונת מצב: DATE</span><p style="color:#b5c0cf;font-size:.85rem">בדיקה יומית מתוכננת ל-07:00 שעון ישראל. אם לא פורסם סרטון חדש, תוכן האתר עשוי להישאר כפי שהיה; תאריך תמונת המצב מציין את הרענון האחרון שבוצע בפועל.</p></div></div><section class="section" id="repos"><div class="wrap"><div class="eyebrow">01 / VERIFIED REPOSITORIES</div><h2>מה עלה בסרטונים</h2><p class="coverage">COVERAGE</p><div class="filter" role="group" aria-label="סינון לפי ערוץ"><button type="button" aria-pressed="true" data-filter="all">הכול</button><button type="button" aria-pressed="false" data-filter="JunSun">JunSun</button><button type="button" aria-pressed="false" data-filter="Github Awesome">Github Awesome</button></div><p class="reading-hint">סמנו מאגרים לקריאה בהמשך. הרשימה נשמרת בדפדפן הזה ומופיעה גם ב-<a href="https://rkinstinct.github.io/data-ai-hub/#reading">DATA&amp;AI</a>; היא אינה מסתנכרנת בין מכשירים.</p><div class="saved-copy-tools"><button type="button" id="copy-saved-repos">העתקת כל המאגרים השמורים</button><button type="button" id="show-saved-repos">הצגת הרשימה להעתקה ידנית</button><p id="saved-copy-status" role="status" aria-live="polite"></p><div id="saved-copy-fallback" hidden><label for="saved-copy-text">רשימת המאגרים השמורים (שם וקישור בכל שורה)</label><textarea id="saved-copy-text" dir="ltr" readonly rows="6"></textarea><p>אם ההעתקה חסומה, לחצו לחיצה ארוכה בתוך הרשימה, בחרו הכול והעתיקו.</p><button type="button" id="select-saved-repos">בחירת כל הטקסט</button></div></div><div class="date-tabs" role="group" aria-label="תאריך תמונת מצב"></div><p id="date-note"></p><p id="shown-count" aria-live="polite"></p><div class="cards"></div><button id="load-more" type="button" class="reading-toggle">טען עוד מאגרים</button></div></section><section class="section" id="videos"><div class="wrap"><div class="eyebrow">02 / ORIGINAL VIDEOS</div><h2>סרטונים שנבדקו</h2><ul><!--VIDEO_LIST--></ul></div></section><section class="section" id="method"><div class="wrap"><div class="eyebrow">03 / METHOD & LIMITS</div><h2>מה הנתונים אומרים - ומה לא</h2><p>כל מאגר מקושר לסרטון המקור ונבדק ישירות מול GitHub. המקור הוא תיאור הסרטון או דף הטקסט הרשמי של הערוץ. כיסוי חלקי מסומן במפורש בתאריך המתאים, ורק מאגרים שאומתו נכללים. בתמונת מצב מלאה נבדקים שלושת הסרטונים האחרונים של JunSun ושני הסרטונים האחרונים של Github Awesome, ללא רף שמעדיף ערוץ אחד. תמונות המצב הקודמות נשמרות בכרטיסיות לפי תאריך. נתוני הכוכבים בתאריך היסטורי נכונים לאותה תמונת מצב, לא להיום. כשפרויקט מופיע בכמה סרטונים או בשני ערוצים, הוא מוצג פעם אחת עם כל קישורי המקור ונכלל בסינון של שני הערוצים. מספר כוכבים הוא סך מצטבר בזמן העדכון, לא מספר כוכבים ביממה, דירוג או המלצה להתקין. תיאורי סרטון יכולים לטעות: בדקו README, רישוי, תחזוקה ואבטחה לפני שימוש ארגוני. לא הותקנו או הורצו מאגרים.</p><p>הסדר כאן הוא סדר הסרטונים (מהחדש לישן) ואז סדר הקישורים בתיאורם, לא טבלת הטרנדים הרשמית. המקור הראשוני הוא שני הערוצים בלבד; GitHub שימש לאימות המאגר והמטא-דאטה. בדיקה יומית יכולה לגלות סרטונים חדשים גם אם הערוצים לא מעלים בכל יום.</p></div></section></main><footer><div class="wrap"><span>GitHub Radar · DATA&AI</span><span>מקורות: JunSun · Github Awesome · GitHub repositories</span></div></footer><script src="https://cdn.jsdelivr.net/npm/fflate@0.8.2/umd/index.js" integrity="sha384-DT0Ls0mO7JmjTnT+oBuMhEJzYJO1zUqzuuMXNdnOmOQRIpN2BgSjvBV/j50NngIT" crossorigin="anonymous"></script><script id="radar-archive" type="application/octet-stream">PACKED_ARCHIVE</script><script>
(async()=>{const raw=Uint8Array.from(atob(document.getElementById('radar-archive').textContent.trim()),c=>c.charCodeAt(0));const text=fflate.strFromU8(fflate.gunzipSync(raw));const archive=JSON.parse(text);const dates=Object.keys(archive).sort().reverse();let selected=dates[0],filter='all',limit=24;const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const READING_KEY='data-ai-reading-list-v1';
function readingList(){try{const list=JSON.parse(localStorage.getItem(READING_KEY)||'[]');return Array.isArray(list)?list.filter(x=>x&&typeof x.url==='string'):[]}catch{return []}}
function readingButton(r){const saved=readingList().some(x=>x.url===r.url);return `<button class="reading-toggle" type="button" data-repo="${e(r.url)}" aria-pressed="${saved}" title="הרשימה נשמרת בדפדפן הזה ומשותפת עם אתר DATA&AI">${saved?'✓ נשמר · ביטול סימון':'＋ לקריאה בהמשך'}</button>`}
function bindReading(rows){document.querySelectorAll('.reading-toggle').forEach(b=>b.addEventListener('click',()=>{const r=rows.find(x=>x.url===b.dataset.repo);if(!r)return;let list=readingList();const saved=list.some(x=>x.url===r.url);list=saved?list.filter(x=>x.url!==r.url):[{name:r.name,description:r.description,url:r.url,savedAt:new Date().toISOString()},...list];try{localStorage.setItem(READING_KEY,JSON.stringify(list))}catch{alert('לא ניתן לשמור בדפדפן הזה. בדקו שהאחסון המקומי זמין.');return}draw()}))}
const draw=()=>{const snap=selected==='all'?{updated:'כל התאריכים',videos:dates.flatMap(d=>archive[d].videos)}:archive[selected];const seen={};const rows=selected==='all'?dates.flatMap(d=>archive[d].repos).filter(r=>seen[r.url]?false:(seen[r.url]=true)):snap.repos;const visible=rows.filter(r=>filter==='all'||(r.channels||[r.channel]).includes(filter));const channels=r=>r.channels||[r.channel];const sources=r=>r.sources||[{channel:r.channel,url:r.video,date:''}];document.querySelector('.coverage').textContent=`${rows.length} מאגרים ייחודיים · JunSun: ${rows.filter(r=>channels(r).includes('JunSun')).length} · Github Awesome: ${rows.filter(r=>channels(r).includes('Github Awesome')).length}. מאגר משותף נספר בשני הערוצים.`;document.getElementById('date-note').textContent=`תמונת מצב: ${snap.updated}. הכרטיסים הישנים נשמרים בכל תאריך; מספרי הכוכבים הם מהבדיקה באותו יום.`;if(snap.partial)document.getElementById('date-note').textContent+=' '+snap.coverage_note;document.querySelector('.cards').innerHTML=visible.slice(0,limit).map(r=>`<article class="card"><div class="eyebrow">${e(channels(r).join(' | '))} / ${e(r.language)}</div><h3 dir="ltr">${e(r.name)}</h3><p>${e(r.description)}</p><div class="meta"><span>★ ${Number(r.stars).toLocaleString('en-US')} <small>בזמן תמונת המצב</small></span><a href="${e(r.url)}" target="_blank" rel="noopener">מאגר ↗</a></div><div class="sources"><small>סרטוני מקור</small>${sources(r).map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.channel)} ${e(s.date)} ↗</a>`).join('')}</div>${readingButton(r)}</article>`).join('');bindReading(rows);document.getElementById('load-more').hidden=limit>=visible.length;document.getElementById('load-more').textContent=`טען עוד מאגרים (${Math.min(limit,visible.length)} מתוך ${visible.length})`;document.getElementById('shown-count').textContent=`מוצגים ${Math.min(limit,visible.length)} מתוך ${visible.length} מאגרים`;document.querySelector('#videos ul').innerHTML=snap.videos.map(v=>`<li><a href="${e(v.url)}" target="_blank" rel="noopener">${e(v.title)}</a> <small>${e(v.channel)} · ${e(v.date)}</small></li>`).join('');document.querySelectorAll('.date-tabs button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.date===selected)))};document.querySelector('.date-tabs').innerHTML='<button data-date="all" aria-pressed="false">כל התאריכים</button>'+dates.map(d=>`<button data-date="${d}" aria-pressed="${d===selected}">${d.split('-').reverse().join('.')}</button>`).join('');document.querySelectorAll('.date-tabs button').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.date;limit=24;draw()}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;limit=24;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw()}));document.getElementById('load-more').addEventListener('click',()=>{limit+=24;draw()});window.addEventListener('storage',ev=>{if(ev.key===READING_KEY)draw()});window.addEventListener('pageshow',()=>draw());draw()})().catch(()=>{document.querySelector('.cards').textContent='לא ניתן לטעון את הארכיון. נסו לפתוח את הקישור בדפדפן הרגיל ולרענן את הדף.'});
</script><script>(()=>{
const button=document.getElementById('copy-saved-repos');if(!button)return;
const status=document.getElementById('saved-copy-status'),fallback=document.getElementById('saved-copy-fallback'),text=document.getElementById('saved-copy-text');
function saved(){try{const raw=JSON.parse(localStorage.getItem('data-ai-reading-list-v1')||'[]');if(!Array.isArray(raw))return [];const seen=new Set();return raw.filter(r=>r&&typeof r.url==='string'&&/^https:\\/\\/github\\.com\\/[\\w.-]+\\/[\\w.-]+\\/?$/.test(r.url)&&!seen.has(r.url.replace(/\\/$/, '').toLowerCase())&&seen.add(r.url.replace(/\\/$/, '').toLowerCase()))}catch{return []}}
function value(){return saved().map(r=>`${String(r.name||r.url.replace('https://github.com/','')).replace(/[\\r\\n]+/g,' ')} - ${r.url}`).join('\\n')}
function show(){const data=value();if(!data){fallback.hidden=true;status.textContent='אין מאגרים שמורים להעתקה. סמנו מאגרים לקריאה בהמשך.';return false}text.value=data;fallback.hidden=false;return true}
function select(){text.focus();text.select();text.setSelectionRange(0,text.value.length)}
button.addEventListener('click',async()=>{const data=value();if(!data){show();return}fallback.hidden=true;status.textContent='מעתיק…';let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(data);copied=true}}catch{}if(!copied){show();select();try{copied=document.execCommand('copy')}catch{}}if(copied){status.textContent=`הועתקו ${saved().length} מאגרים שמורים.`;fallback.hidden=true}else{status.textContent='הדפדפן חסם העתקה אוטומטית. הרשימה מוכנה להעתקה ידנית.';show();select()}});
document.getElementById('show-saved-repos').addEventListener('click',()=>{if(show()){status.textContent='הרשימה מוכנה להעתקה ידנית.';select()}});
document.getElementById('select-saved-repos').addEventListener('click',select);
window.addEventListener('storage',()=>{fallback.hidden=true;status.textContent=''});
})();
</script></body></html>'''
coverage=f"{len(verified)} מאגרים ייחודיים · JunSun: {sum('JunSun' in r['channels'] for r in verified)} · Github Awesome: {sum('Github Awesome' in r['channels'] for r in verified)}. מאגר משותף נספר בשני הערוצים."
day=datetime.datetime.now(__import__('zoneinfo').ZoneInfo('Asia/Jerusalem')).strftime('%Y-%m-%d')
previous=archive.get(day,{})
by_name={r['name'].lower():r for r in verified}
for old in previous.get('repos',[]):
 if old['name'].lower() not in by_name:verified.append(old)
old_video_urls={v['url'] for ch,v in videos}
retained_videos=[v for v in previous.get('videos',[]) if v['url'] not in old_video_urls]
archive[day]={'day':day,'updated':now,'videos':[{'channel':ch,'title':v['title'],'date':v['date'],'url':v['url']} for ch,v in videos]+retained_videos,'repos':verified}
(ROOT/'archive.json').write_text(json.dumps(archive,ensure_ascii=False))
packed=base64.b64encode(gzip.compress(json.dumps(archive,ensure_ascii=False,separators=(',',':')).encode())).decode()
page=page.replace('PACKED_ARCHIVE',packed).replace('COVERAGE',esc(coverage)).replace('DATE',esc(now)).replace('CARDS','\n'.join(map(card,verified))).replace('<!--VIDEO_LIST-->','\n'.join(video(ch,v) for ch,v in videos))
(ROOT/'index.html').write_text(page)
print(f'Built {len(verified)} repos from {len(videos)} videos; {now}')
